#include <stdio.h>
#include <stdlib.h>
#include <string.h>

constexpr size_t MAX_VOCI = 64;
constexpr size_t MAX_NOTE = 16;

typedef struct voce {
    char nome[32];
    int qty;
    long long prezzo_cent;
} voce_t;

static bool scrivi_ricevuta(const char *path_tmp, const voce_t *voci, size_t n_voci) {
    FILE *fp = fopen(path_tmp, "w");
    if (fp == nullptr) { return false; }
    bool ok = (fputs("=== RICEVUTA ===\n", fp) != EOF);
    long long totale = 0;
    if (n_voci == 0) {
        ok = ok && (fputs("Nessuna voce.\n", fp) != EOF);
    } else {
        for (size_t i = 0; i < n_voci && ok; ++i) {
            long long sub = (long long)voci[i].qty * voci[i].prezzo_cent;
            totale += sub;
            ok = (fprintf(fp, "%s x%d = %lld.%02lld\n", voci[i].nome, voci[i].qty, sub / 100, sub % 100) >= 0);
        }
    }
    for (int i = 0; i < 16 && ok; ++i) {
        ok = (fputc('-', fp) != EOF);
    }
    ok = ok && (fputc('\n', fp) != EOF);
    ok = ok && (fprintf(fp, "Totale: %lld.%02lld\n", totale / 100, totale % 100) >= 0);
    ok = ok && (fflush(fp) == 0) && (ferror(fp) == 0);
    if (fclose(fp) != 0) { ok = false; }
    return ok;
}

static bool aggiungi_note(const char *path, char note[MAX_NOTE][128], size_t n_note) {
    if (n_note == 0) { return true; }
    FILE *fp = fopen(path, "a");
    if (fp == nullptr) { return false; }
    bool ok = (fputs("Note:\n", fp) != EOF);
    for (size_t i = 0; i < n_note && ok; ++i) {
        ok = (fprintf(fp, "- %s\n", note[i]) >= 0);
    }
    if (fclose(fp) != 0) { ok = false; }
    return ok;
}

int main(void) {
    const char *file_tmp = "ricevuta_20_1.tmp";
    const char *file_fin = "ricevuta_20_1.txt";
    voce_t voci[MAX_VOCI] = {};
    char note[MAX_NOTE][128] = {};
    size_t n_voci = 0, n_note = 0;
    char riga[256], cmd[16], extra = '\0';

    while (fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
        if (sscanf(riga, "%15s", cmd) != 1) { continue; }
        if (strcmp(cmd, "VOCE") == 0) {
            voce_t v = {};
            if (n_voci >= MAX_VOCI ||
                sscanf(riga, "VOCE %31s %d %lld %c", v.nome, &v.qty, &v.prezzo_cent, &extra) != 3 ||
                v.qty < 1 || v.qty > 1000 || v.prezzo_cent < 0 || v.prezzo_cent > 1000000) {
                fprintf(stderr, "Errore: voce non valida.\n");
                return EXIT_FAILURE;
            }
            voci[n_voci++] = v;
        } else if (strcmp(cmd, "NOTA") == 0) {
            const char *p = riga + 4;
            while (*p == ' ' || *p == '\t') { ++p; }
            size_t len = strlen(p);
            while (len > 0 && (p[len - 1] == '\n' || p[len - 1] == '\r')) { --len; }
            if (n_note >= MAX_NOTE || len == 0 || len >= sizeof(note[0])) {
                fprintf(stderr, "Errore: nota non valida.\n");
                return EXIT_FAILURE;
            }
            memcpy(note[n_note], p, len);
            note[n_note][len] = '\0';
            ++n_note;
        } else {
            fprintf(stderr, "Errore: comando sconosciuto.\n");
            return EXIT_FAILURE;
        }
    }
    if (!scrivi_ricevuta(file_tmp, voci, n_voci) || rename(file_tmp, file_fin) != 0 ||
        !aggiungi_note(file_fin, note, n_note)) {
        remove(file_tmp);
        remove(file_fin);
        fprintf(stderr, "Errore di scrittura file.\n");
        return EXIT_FAILURE;
    }
    FILE *in = fopen(file_fin, "r");
    if (in == nullptr) {
        remove(file_fin);
        return EXIT_FAILURE;
    }
    while (fgets(riga, (int)sizeof(riga), in) != nullptr) {
        fputs(riga, stdout);
    }
    bool err = (ferror(in) != 0);
    fclose(in);
    if (err || remove(file_fin) != 0) {
        fprintf(stderr, "Errore di lettura o rimozione.\n");
        return EXIT_FAILURE;
    }
    printf("Archivio rimosso: OK\n");
    return EXIT_SUCCESS;
}

#include <ctype.h>
#include <errno.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static bool parsa_intero(const char *s, long *out) {
    if (s == nullptr || *s == '\0' || isspace((unsigned char)*s)) { return false; }
    char *end = nullptr;
    errno = 0;
    long v = strtol(s, &end, 10);
    if (errno == ERANGE || end == s || *end != '\0') { return false; }
    *out = v;
    return true;
}

static bool parsa_record(char *riga, int *livello, long long *durata) {
    char *p1 = strchr(riga, ';');
    if (p1 == nullptr) { return false; }
    char *p2 = strchr(p1 + 1, ';');
    if (p2 == nullptr || strchr(p2 + 1, ';') != nullptr) { return false; }
    *p1 = '\0';
    *p2 = '\0';
    if (strcmp(riga, "INFO") == 0) { *livello = 0; }
    else if (strcmp(riga, "WARN") == 0) { *livello = 1; }
    else if (strcmp(riga, "ERR") == 0) { *livello = 2; }
    else { return false; }
    long cod = 0, dur = 0;
    if (!parsa_intero(p1 + 1, &cod) || cod < INT32_MIN || cod > INT32_MAX) { return false; }
    if (!parsa_intero(p2 + 1, &dur) || dur < 0) { return false; }
    *durata = (long long)dur;
    return true;
}

int main(void) {
    const char *path = "log_20_2.txt";
    FILE *out = fopen(path, "w");
    if (out == nullptr) { return EXIT_FAILURE; }
    int ch = 0;
    while ((ch = fgetc(stdin)) != EOF) {
        if (fputc(ch, out) == EOF) { fclose(out); remove(path); return EXIT_FAILURE; }
    }
    if (ferror(stdin) != 0 || fclose(out) != 0) { remove(path); return EXIT_FAILURE; }

    FILE *fp = fopen(path, "r");
    if (fp == nullptr) { remove(path); return EXIT_FAILURE; }
    size_t c_liv[3] = {0, 0, 0};
    size_t ignorate = 0, malformate = 0, troncate = 0;
    long long somma_durata = 0;
    char buf[32];
    while (fgets(buf, (int)sizeof(buf), fp) != nullptr) {
        size_t len = strlen(buf);
        bool ha_nl = (len > 0 && buf[len - 1] == '\n');
        if (!ha_nl && len == sizeof(buf) - 1) {
            int extra = fgetc(fp);
            if (extra != EOF && extra != '\n') {
                while (extra != EOF && extra != '\n') { extra = fgetc(fp); }
                ++troncate;
                continue;
            }
        }
        while (len > 0 && (buf[len - 1] == '\n' || buf[len - 1] == '\r')) { buf[--len] = '\0'; }
        size_t pos = 0;
        while (buf[pos] != '\0' && isspace((unsigned char)buf[pos])) { ++pos; }
        if (buf[pos] == '\0' || buf[pos] == '#') { ++ignorate; continue; }
        int liv = 0;
        long long dur = 0;
        if (parsa_record(buf + pos, &liv, &dur)) {
            ++c_liv[liv];
            somma_durata += dur;
        } else {
            ++malformate;
        }
    }
    printf("Stato fine lettura: EOF=%d ERR=%d\n", (feof(fp) != 0) ? 1 : 0, (ferror(fp) != 0) ? 1 : 0);
    (void)fputc('X', fp);
    printf("Dopo scrittura su sola lettura: ERR=%d\n", (ferror(fp) != 0) ? 1 : 0);
    clearerr(fp);
    printf("Dopo clearerr: EOF=%d ERR=%d\n", (feof(fp) != 0) ? 1 : 0, (ferror(fp) != 0) ? 1 : 0);
    fclose(fp);
    if (remove(path) != 0) { return EXIT_FAILURE; }
    size_t valide = c_liv[0] + c_liv[1] + c_liv[2];
    printf("Valide: %zu (INFO=%zu WARN=%zu ERR=%zu) Durata=%lld ms\n", valide, c_liv[0], c_liv[1], c_liv[2], somma_durata);
    printf("Ignorate: %zu Malformate: %zu Troncate: %zu\n", ignorate, malformate, troncate);
    return EXIT_SUCCESS;
}

#include <inttypes.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

constexpr size_t DIM_BLOCCO = 16;

static bool comprimi_rle(const char *src, const char *dst, size_t *byte_orig, size_t *byte_comp) {
    FILE *fin = fopen(src, "rb");
    FILE *fout = fopen(dst, "wb");
    if (fin == nullptr || fout == nullptr) {
        if (fin != nullptr) { fclose(fin); }
        if (fout != nullptr) { fclose(fout); }
        return false;
    }
    uint8_t buf[DIM_BLOCCO];
    bool attivo = false;
    uint8_t val = 0, cnt = 0;
    size_t tot_in = 0, tot_out = 0;
    bool ok = true;
    size_t letti = 0;
    while (ok && (letti = fread(buf, 1, sizeof(buf), fin)) > 0) {
        tot_in += letti;
        for (size_t i = 0; i < letti && ok; ++i) {
            if (!attivo) {
                val = buf[i]; cnt = 1; attivo = true;
            } else if (buf[i] == val && cnt < 255) {
                ++cnt;
            } else {
                uint8_t coppia[2] = {cnt, val};
                ok = (fwrite(coppia, 1, 2, fout) == 2);
                tot_out += 2;
                val = buf[i]; cnt = 1;
            }
        }
    }
    if (ok && ferror(fin) != 0) { ok = false; }
    if (ok && attivo) {
        uint8_t coppia[2] = {cnt, val};
        ok = (fwrite(coppia, 1, 2, fout) == 2);
        tot_out += 2;
    }
    if (fclose(fin) != 0) { ok = false; }
    if (fclose(fout) != 0) { ok = false; }
    if (ok) { *byte_orig = tot_in; *byte_comp = tot_out; }
    return ok;
}

static bool decomprimi_rle(const char *src, const char *dst) {
    FILE *fin = fopen(src, "rb");
    FILE *fout = fopen(dst, "wb");
    if (fin == nullptr || fout == nullptr) {
        if (fin != nullptr) { fclose(fin); }
        if (fout != nullptr) { fclose(fout); }
        return false;
    }
    uint8_t buf[DIM_BLOCCO], espanso[255];
    bool ok = true;
    size_t letti = 0;
    while (ok && (letti = fread(buf, 1, sizeof(buf), fin)) > 0) {
        if ((letti % 2) != 0) { ok = false; break; }
        for (size_t i = 0; i < letti && ok; i += 2) {
            if (buf[i] == 0) { ok = false; break; }
            memset(espanso, buf[i + 1], buf[i]);
            ok = (fwrite(espanso, 1, buf[i], fout) == buf[i]);
        }
    }
    if (ok && ferror(fin) != 0) { ok = false; }
    if (fclose(fin) != 0) { ok = false; }
    if (fclose(fout) != 0) { ok = false; }
    return ok;
}

static bool file_identici(const char *a, const char *b) {
    FILE *fa = fopen(a, "rb");
    FILE *fb = fopen(b, "rb");
    if (fa == nullptr || fb == nullptr) {
        if (fa != nullptr) { fclose(fa); }
        if (fb != nullptr) { fclose(fb); }
        return false;
    }
    uint8_t ba[DIM_BLOCCO], bb[DIM_BLOCCO];
    bool uguali = true;
    while (true) {
        size_t na = fread(ba, 1, sizeof(ba), fa);
        size_t nb = fread(bb, 1, sizeof(bb), fb);
        if (na != nb || (na > 0 && memcmp(ba, bb, na) != 0)) { uguali = false; break; }
        if (na == 0) {
            if (ferror(fa) != 0 || ferror(fb) != 0) { uguali = false; }
            break;
        }
    }
    fclose(fa);
    fclose(fb);
    return uguali;
}

int main(void) {
    const char *f_orig = "orig_20_3.bin", *f_comp = "comp_20_3.rle", *f_ric = "ric_20_3.bin";
    FILE *fo = fopen(f_orig, "wb");
    if (fo == nullptr) { return EXIT_FAILURE; }
    char riga[128], extra = '\0';
    while (fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
        int cnt = 0;
        unsigned int hexv = 0;
        if (sscanf(riga, " %c", &extra) != 1) { continue; }
        if (sscanf(riga, "RUN %d %x %c", &cnt, &hexv, &extra) != 2 || cnt < 1 || cnt > 600 || hexv > 0xFFU) {
            fclose(fo); remove(f_orig); return EXIT_FAILURE;
        }
        uint8_t b = (uint8_t)hexv;
        for (int i = 0; i < cnt; ++i) {
            if (fwrite(&b, 1, 1, fo) != 1) { fclose(fo); remove(f_orig); return EXIT_FAILURE; }
        }
    }
    if (fclose(fo) != 0) { remove(f_orig); return EXIT_FAILURE; }

    size_t n_orig = 0, n_comp = 0;
    if (!comprimi_rle(f_orig, f_comp, &n_orig, &n_comp) || !decomprimi_rle(f_comp, f_ric) ||
        !file_identici(f_orig, f_ric)) {
        remove(f_orig); remove(f_comp); remove(f_ric); return EXIT_FAILURE;
    }
    printf("Originale: %zu byte\nCompresso: %zu byte (%zu coppie)\nRLE:", n_orig, n_comp, n_comp / 2);
    if (n_comp == 0) {
        printf(" (vuoto)\n");
    } else {
        FILE *fc = fopen(f_comp, "rb");
        if (fc == nullptr) { remove(f_orig); remove(f_comp); remove(f_ric); return EXIT_FAILURE; }
        uint8_t coppia[2];
        while (fread(coppia, 1, 2, fc) == 2) {
            printf(" %" PRIu8 "x%02" PRIX8, coppia[0], coppia[1]);
        }
        printf("\n");
        fclose(fc);
    }
    printf("Integrita: OK\n");
    if (remove(f_orig) != 0 || remove(f_comp) != 0 || remove(f_ric) != 0) { return EXIT_FAILURE; }
    return EXIT_SUCCESS;
}

