#include "archivio_rec.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static constexpr size_t DIM_REC = 24;

struct archivio_rec {
    FILE *fp;
    size_t num_record;
};

static void codifica_rec(const record_conto_t *r, uint8_t out[DIM_REC]) {
    memset(out, 0, DIM_REC);
    for (size_t i = 0; i < 4; ++i) { out[i] = (uint8_t)((r->id >> (8 * i)) & 0xFFU); }
    out[4] = r->attivo ? 1U : 0U;
    uint64_t s = (uint64_t)r->saldo_cent;
    for (size_t i = 0; i < 8; ++i) { out[8 + i] = (uint8_t)((s >> (8 * i)) & 0xFFU); }
    for (size_t i = 0; i < 7 && r->codice[i] != '\0'; ++i) { out[16 + i] = (uint8_t)r->codice[i]; }
}

static void decodifica_rec(const uint8_t in[DIM_REC], record_conto_t *r) {
    uint32_t id = 0;
    for (size_t i = 0; i < 4; ++i) { id |= ((uint32_t)in[i]) << (8 * i); }
    uint64_t s = 0;
    for (size_t i = 0; i < 8; ++i) { s |= ((uint64_t)in[8 + i]) << (8 * i); }
    r->id = id;
    r->attivo = (in[4] != 0);
    r->saldo_cent = (int64_t)s;
    memcpy(r->codice, in + 16, 7);
    r->codice[7] = '\0';
}

archivio_rec_t *arch_crea(void) {
    archivio_rec_t *a = malloc(sizeof(*a));
    if (a == nullptr) { return nullptr; }
    a->fp = tmpfile();
    if (a->fp == nullptr) { free(a); return nullptr; }
    a->num_record = 0;
    return a;
}

void arch_distruggi(archivio_rec_t *a) {
    if (a == nullptr) { return; }
    if (a->fp != nullptr) { fclose(a->fp); }
    free(a);
}

bool arch_aggiungi(archivio_rec_t *a, const record_conto_t *r, size_t *idx_out) {
    if (a == nullptr || r == nullptr) { return false; }
    uint8_t raw[DIM_REC];
    codifica_rec(r, raw);
    if (fseek(a->fp, (long)(a->num_record * DIM_REC), SEEK_SET) != 0) { return false; }
    if (fwrite(raw, 1, DIM_REC, a->fp) != DIM_REC || fflush(a->fp) != 0) { return false; }
    if (idx_out != nullptr) { *idx_out = a->num_record; }
    ++a->num_record;
    return true;
}

bool arch_leggi(archivio_rec_t *a, size_t idx, record_conto_t *out) {
    if (a == nullptr || out == nullptr || idx >= a->num_record) { return false; }
    uint8_t raw[DIM_REC];
    if (fseek(a->fp, (long)(idx * DIM_REC), SEEK_SET) != 0) { return false; }
    if (fread(raw, 1, DIM_REC, a->fp) != DIM_REC) { return false; }
    decodifica_rec(raw, out);
    return true;
}

bool arch_aggiorna_saldo(archivio_rec_t *a, size_t idx, int64_t delta_cent, int64_t *nuovo_saldo) {
    record_conto_t rec = {};
    if (!arch_leggi(a, idx, &rec) || !rec.attivo) { return false; }
    rec.saldo_cent += delta_cent;
    uint8_t raw[DIM_REC];
    codifica_rec(&rec, raw);
    if (fseek(a->fp, -(long)DIM_REC, SEEK_CUR) != 0) { return false; }
    if (fwrite(raw, 1, DIM_REC, a->fp) != DIM_REC || fflush(a->fp) != 0) { return false; }
    if (nuovo_saldo != nullptr) { *nuovo_saldo = rec.saldo_cent; }
    return true;
}

bool arch_disattiva(archivio_rec_t *a, size_t idx) {
    record_conto_t rec = {};
    if (!arch_leggi(a, idx, &rec) || !rec.attivo) { return false; }
    rec.attivo = false;
    uint8_t raw[DIM_REC];
    codifica_rec(&rec, raw);
    if (fseek(a->fp, -(long)DIM_REC, SEEK_CUR) != 0) { return false; }
    return fwrite(raw, 1, DIM_REC, a->fp) == DIM_REC && fflush(a->fp) == 0;
}

size_t arch_scansiona_attivi(archivio_rec_t *a, int64_t *somma_saldi) {
    if (a == nullptr) { return 0; }
    rewind(a->fp);
    size_t attivi = 0;
    int64_t somma = 0;
    uint8_t raw[DIM_REC];
    for (size_t i = 0; i < a->num_record; ++i) {
        if (fread(raw, 1, DIM_REC, a->fp) != DIM_REC) { break; }
        record_conto_t rec = {};
        decodifica_rec(raw, &rec);
        if (rec.attivo) { ++attivi; somma += rec.saldo_cent; }
    }
    if (somma_saldi != nullptr) { *somma_saldi = somma; }
    return attivi;
}

long arch_dimensione_byte(archivio_rec_t *a) {
    if (a == nullptr || fseek(a->fp, (long)(a->num_record * DIM_REC), SEEK_SET) != 0) { return -1L; }
    return ftell(a->fp);
}

size_t arch_num_record(const archivio_rec_t *a) { return (a != nullptr) ? a->num_record : 0; }

