#include <inttypes.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "archivio_rec.h"

int main(void) {
    archivio_rec_t *a = arch_crea();
    if (a == nullptr) { return EXIT_FAILURE; }
    char riga[256], cmd[16], cod[16], extra = '\0';
    while (fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
        if (sscanf(riga, "%15s", cmd) != 1) { continue; }
        unsigned long id = 0;
        long long val = 0;
        size_t idx = 0;
        if (strcmp(cmd, "ADD") == 0 && sscanf(riga, "ADD %lu %7s %lld %c", &id, cod, &val, &extra) == 3 && id <= UINT32_MAX) {
            record_conto_t r = {.id = (uint32_t)id, .attivo = true, .saldo_cent = (int64_t)val};
            memcpy(r.codice, cod, strlen(cod) + 1);
            if (!arch_aggiungi(a, &r, &idx)) { arch_distruggi(a); return EXIT_FAILURE; }
            printf("ADD idx=%zu id=%" PRIu32 "\n", idx, r.id);
        } else if (strcmp(cmd, "GET") == 0 && sscanf(riga, "GET %zu %c", &idx, &extra) == 1) {
            record_conto_t r = {};
            if (arch_leggi(a, idx, &r)) {
                printf("GET[%zu]: id=%" PRIu32 " cod=%s saldo=%" PRId64 " stato=%s\n",
                       idx, r.id, r.codice, r.saldo_cent, r.attivo ? "ATTIVO" : "DISATTIVO");
            } else { printf("GET[%zu]: FUORI LIMITI\n", idx); }
        } else if (strcmp(cmd, "DELTA") == 0 && sscanf(riga, "DELTA %zu %lld %c", &idx, &val, &extra) == 2) {
            int64_t nuovo = 0;
            if (arch_aggiorna_saldo(a, idx, (int64_t)val, &nuovo)) {
                printf("DELTA[%zu]: saldo=%" PRId64 "\n", idx, nuovo);
            } else { printf("DELTA[%zu]: NON VALIDO\n", idx); }
        } else if (strcmp(cmd, "DEL") == 0 && sscanf(riga, "DEL %zu %c", &idx, &extra) == 1) {
            printf("DEL[%zu]: %s\n", idx, arch_disattiva(a, idx) ? "OK" : "NON VALIDO");
        } else if (strcmp(cmd, "SUM") == 0 && sscanf(riga, "SUM %c", &extra) != 1) {
            int64_t tot = 0;
            size_t att = arch_scansiona_attivi(a, &tot);
            printf("SUM: attivi=%zu/%zu totale=%" PRId64 "\n", att, arch_num_record(a), tot);
        } else if (strcmp(cmd, "SIZE") == 0 && sscanf(riga, "SIZE %c", &extra) != 1) {
            printf("SIZE: %ld byte\n", arch_dimensione_byte(a));
        } else { arch_distruggi(a); return EXIT_FAILURE; }
    }
    arch_distruggi(a);
    return EXIT_SUCCESS;
}

