#ifndef CATALOGO_BIN_H
#define CATALOGO_BIN_H

#include <stddef.h>
#include <stdint.h>

typedef enum cat_esito {
    CAT_OK = 0,
    CAT_ERR_IO,
    CAT_ERR_MAGIC,
    CAT_ERR_VERSIONE,
    CAT_ERR_CHECKSUM,
    CAT_ERR_TRONCATO,
    CAT_ERR_LIMITE,
    CAT_ERR_MEM
} cat_esito_t;

typedef struct articolo {
    uint32_t codice;
    char *titolo;
    int32_t prezzo_cent;
    uint16_t giacenza;
    uint8_t priorita;
} articolo_t;

typedef struct catalogo {
    articolo_t *dati;
    size_t len;
    size_t cap;
} catalogo_t;

void cat_libera(catalogo_t *c);
bool cat_aggiungi(catalogo_t *c, uint32_t codice, const char *titolo, int32_t prezzo_cent, uint16_t giacenza, uint8_t priorita);
cat_esito_t cat_salva(const catalogo_t *c, const char *path, uint16_t versione, size_t *byte_scritti);
cat_esito_t cat_carica(catalogo_t *c, const char *path, uint16_t *ver_letta);
const char *cat_esito_nome(cat_esito_t e);

#endif

