#include "catalogo_bin.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static constexpr uint32_t MAX_ARTICOLI = 1024;
static constexpr uint16_t MAX_LEN_TITOLO = 128;
static const uint8_t MAGIC[4] = {'C', 'A', 'T', 'B'};

static void scrivi_u16_le(uint8_t b[2], uint16_t v) { b[0] = (uint8_t)(v & 0xFFU); b[1] = (uint8_t)((v >> 8) & 0xFFU); }
static void scrivi_u32_le(uint8_t b[4], uint32_t v) {
    for (size_t i = 0; i < 4; ++i) { b[i] = (uint8_t)((v >> (8 * i)) & 0xFFU); }
}
static uint16_t leggi_u16_le(const uint8_t b[2]) { return (uint16_t)((uint16_t)b[0] | ((uint16_t)b[1] << 8)); }
static uint32_t leggi_u32_le(const uint8_t b[4]) {
    uint32_t v = 0; for (size_t i = 0; i < 4; ++i) { v |= ((uint32_t)b[i]) << (8 * i); } return v;
}
static uint32_t fnv1a_aggiorna(uint32_t h, const uint8_t *dati, size_t n) {
    for (size_t i = 0; i < n; ++i) { h ^= dati[i]; h *= 16777619U; } return h;
}

void cat_libera(catalogo_t *c) {
    if (c == nullptr) { return; }
    for (size_t i = 0; i < c->len; ++i) { free(c->dati[i].titolo); }
    free(c->dati); c->dati = nullptr; c->len = 0; c->cap = 0;
}

bool cat_aggiungi(catalogo_t *c, uint32_t codice, const char *titolo, int32_t prezzo_cent, uint16_t giacenza, uint8_t priorita) {
    if (c == nullptr || titolo == nullptr || c->len >= MAX_ARTICOLI) { return false; }
    size_t tlen = strlen(titolo);
    if (tlen > MAX_LEN_TITOLO) { return false; }
    if (c->len == c->cap) {
        size_t nuova = (c->cap == 0) ? 4 : c->cap * 2;
        articolo_t *tmp = realloc(c->dati, nuova * sizeof(*tmp));
        if (tmp == nullptr) { return false; }
        c->dati = tmp; c->cap = nuova;
    }
    char *copia = malloc(tlen + 1);
    if (copia == nullptr) { return false; }
    memcpy(copia, titolo, tlen + 1);
    c->dati[c->len++] = (articolo_t){.codice = codice, .titolo = copia, .prezzo_cent = prezzo_cent, .giacenza = giacenza, .priorita = priorita};
    return true;
}

cat_esito_t cat_salva(const catalogo_t *c, const char *path, uint16_t versione, size_t *byte_scritti) {
    if (c == nullptr || path == nullptr || (versione != 1 && versione != 2)) { return CAT_ERR_VERSIONE; }
    FILE *fp = fopen(path, "wb");
    if (fp == nullptr) { return CAT_ERR_IO; }
    uint8_t hdr[16] = {};
    if (fwrite(hdr, 1, 16, fp) != 16) { fclose(fp); return CAT_ERR_IO; }
    uint32_t h = 2166136261U;
    size_t tot = 16;
    for (size_t i = 0; i < c->len; ++i) {
        const articolo_t *a = &c->dati[i];
        uint16_t tlen = (uint16_t)strlen(a->titolo);
        uint8_t rec[13]; size_t rlen = 0;
        scrivi_u32_le(rec + 0, a->codice); scrivi_u32_le(rec + 4, (uint32_t)a->prezzo_cent); scrivi_u16_le(rec + 8, a->giacenza);
        rlen = 10;
        if (versione == 2) { rec[rlen++] = a->priorita; }
        scrivi_u16_le(rec + rlen, tlen); rlen += 2;
        h = fnv1a_aggiorna(h, rec, rlen);
        h = fnv1a_aggiorna(h, (const uint8_t *)a->titolo, tlen);
        if (fwrite(rec, 1, rlen, fp) != rlen || (tlen > 0 && fwrite(a->titolo, 1, tlen, fp) != tlen)) {
            fclose(fp); return CAT_ERR_IO;
        }
        tot += rlen + tlen;
    }
    memcpy(hdr, MAGIC, 4); scrivi_u16_le(hdr + 4, versione); scrivi_u16_le(hdr + 6, 0);
    scrivi_u32_le(hdr + 8, (uint32_t)c->len); scrivi_u32_le(hdr + 12, h);
    if (fseek(fp, 0L, SEEK_SET) != 0 || fwrite(hdr, 1, 16, fp) != 16 || fclose(fp) != 0) { return CAT_ERR_IO; }
    if (byte_scritti != nullptr) { *byte_scritti = tot; }
    return CAT_OK;
}

cat_esito_t cat_carica(catalogo_t *c, const char *path, uint16_t *ver_letta) {
    if (c == nullptr || path == nullptr) { return CAT_ERR_IO; }
    FILE *fp = fopen(path, "rb");
    if (fp == nullptr) { return CAT_ERR_IO; }
    uint8_t hdr[16];
    if (fread(hdr, 1, 16, fp) != 16) { bool e = (ferror(fp) != 0); fclose(fp); return e ? CAT_ERR_IO : CAT_ERR_TRONCATO; }
    if (memcmp(hdr, MAGIC, 4) != 0) { fclose(fp); return CAT_ERR_MAGIC; }
    uint16_t ver = leggi_u16_le(hdr + 4);
    if (ver != 1 && ver != 2) { fclose(fp); return CAT_ERR_VERSIONE; }
    uint32_t n = leggi_u32_le(hdr + 8), csum = leggi_u32_le(hdr + 12);
    if (n > MAX_ARTICOLI) { fclose(fp); return CAT_ERR_LIMITE; }
    catalogo_t tmp = {};
    uint32_t h = 2166136261U;
    size_t fissa = (ver == 2) ? 13 : 12;
    for (uint32_t i = 0; i < n; ++i) {
        uint8_t rec[13];
        if (fread(rec, 1, fissa, fp) != fissa) { cat_libera(&tmp); fclose(fp); return CAT_ERR_TRONCATO; }
        uint32_t cod = leggi_u32_le(rec + 0); int32_t prezzo = (int32_t)leggi_u32_le(rec + 4); uint16_t giac = leggi_u16_le(rec + 8);
        uint8_t prio = (ver == 2) ? rec[10] : 1;
        uint16_t tlen = leggi_u16_le(rec + ((ver == 2) ? 11 : 10));
        if (tlen > MAX_LEN_TITOLO) { cat_libera(&tmp); fclose(fp); return CAT_ERR_LIMITE; }
        char titolo[MAX_LEN_TITOLO + 1];
        if (tlen > 0 && fread(titolo, 1, tlen, fp) != tlen) { cat_libera(&tmp); fclose(fp); return CAT_ERR_TRONCATO; }
        titolo[tlen] = '\0';
        h = fnv1a_aggiorna(h, rec, fissa); h = fnv1a_aggiorna(h, (const uint8_t *)titolo, tlen);
        if (!cat_aggiungi(&tmp, cod, titolo, prezzo, giac, prio)) { cat_libera(&tmp); fclose(fp); return CAT_ERR_MEM; }
    }
    bool extra = (fgetc(fp) != EOF); fclose(fp);
    if (extra || h != csum) { cat_libera(&tmp); return CAT_ERR_CHECKSUM; }
    cat_libera(c); *c = tmp;
    if (ver_letta != nullptr) { *ver_letta = ver; }
    return CAT_OK;
}

const char *cat_esito_nome(cat_esito_t e) {
    switch (e) {
        case CAT_OK: return "OK"; case CAT_ERR_IO: return "IO"; case CAT_ERR_MAGIC: return "MAGIC";
        case CAT_ERR_VERSIONE: return "VERSIONE"; case CAT_ERR_CHECKSUM: return "CHECKSUM";
        case CAT_ERR_TRONCATO: return "TRONCATO"; case CAT_ERR_LIMITE: return "LIMITE";
        case CAT_ERR_MEM: return "MEM"; default: return "SCONOSCIUTO";
    }
}

