#include <inttypes.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "catalogo_bin.h"

static bool corrompi_byte(const char *path, long off, uint8_t val) {
    FILE *fp = fopen(path, "r+b");
    if (fp == nullptr) { return false; }
    bool ok = (fseek(fp, off, SEEK_SET) == 0 && fwrite(&val, 1, 1, fp) == 1);
    if (fclose(fp) != 0) { ok = false; }
    return ok;
}

static bool tronca_file(const char *path, size_t nuova_len) {
    const char *tmp = "catalogo_20_5.tmp";
    FILE *fin = fopen(path, "rb"), *fout = fopen(tmp, "wb");
    if (fin == nullptr || fout == nullptr) {
        if (fin != nullptr) { fclose(fin); }
        if (fout != nullptr) { fclose(fout); }
        return false;
    }
    bool ok = true;
    for (size_t i = 0; i < nuova_len && ok; ++i) {
        int c = fgetc(fin);
        if (c == EOF) { break; }
        ok = (fputc(c, fout) != EOF);
    }
    if (fclose(fin) != 0) { ok = false; }
    if (fclose(fout) != 0) { ok = false; }
    if (!ok || rename(tmp, path) != 0) { remove(tmp); return false; }
    return true;
}

int main(void) {
    const char *path = "catalogo_20_5.bin";
    catalogo_t cat = {};
    char riga[256], cmd[16], titolo[129], extra = '\0';
    while (fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
        if (sscanf(riga, "%15s", cmd) != 1) { continue; }
        unsigned long cod = 0; long long prezzo = 0; unsigned int giac = 0, prio = 0, ver = 0, hexv = 0;
        long off = 0; size_t nlen = 0;
        if (strcmp(cmd, "ADD") == 0 && sscanf(riga, "ADD %lu %lld %u %u %128s %c", &cod, &prezzo, &giac, &prio, titolo, &extra) == 5) {
            if (!cat_aggiungi(&cat, (uint32_t)cod, titolo, (int32_t)prezzo, (uint16_t)giac, (uint8_t)prio)) { cat_libera(&cat); remove(path); return EXIT_FAILURE; }
            printf("ADD %lu: OK\n", cod);
        } else if (strcmp(cmd, "SAVE") == 0 && sscanf(riga, "SAVE %u %c", &ver, &extra) == 1) {
            size_t scritti = 0;
            cat_esito_t es = cat_salva(&cat, path, (uint16_t)ver, &scritti);
            if (es != CAT_OK) { printf("SAVE ERRORE: %s\n", cat_esito_nome(es)); }
            else { printf("SAVE v%u: OK (%zu articoli, %zu byte)\n", ver, cat.len, scritti); }
        } else if (strcmp(cmd, "LOAD") == 0 && sscanf(riga, "LOAD %c", &extra) != 1) {
            uint16_t vl = 0;
            cat_esito_t es = cat_carica(&cat, path, &vl);
            if (es != CAT_OK) { printf("LOAD ERRORE: %s\n", cat_esito_nome(es)); }
            else { printf("LOAD v%" PRIu16 ": OK (%zu articoli)\n", vl, cat.len); }
        } else if (strcmp(cmd, "LIST") == 0 && sscanf(riga, "LIST %c", &extra) != 1) {
            if (cat.len == 0) { printf("(vuoto)\n"); }
            for (size_t i = 0; i < cat.len; ++i) {
                const articolo_t *a = &cat.dati[i];
                printf("#%zu cod=%" PRIu32 " prezzo=%" PRId32 " giac=%" PRIu16 " prio=%" PRIu8 " titolo=%s\n", i, a->codice, a->prezzo_cent, a->giacenza, a->priorita, a->titolo);
            }
        } else if (strcmp(cmd, "CORROMPI") == 0 && sscanf(riga, "CORROMPI %ld %x %c", &off, &hexv, &extra) == 2 && off >= 0 && hexv <= 0xFFU) {
            if (!corrompi_byte(path, off, (uint8_t)hexv)) { cat_libera(&cat); remove(path); return EXIT_FAILURE; }
            printf("CORROMPI[%ld]: OK\n", off);
        } else if (strcmp(cmd, "TRONCA") == 0 && sscanf(riga, "TRONCA %zu %c", &nlen, &extra) == 1) {
            if (!tronca_file(path, nlen)) { cat_libera(&cat); remove(path); return EXIT_FAILURE; }
            printf("TRONCA %zu: OK\n", nlen);
        } else { cat_libera(&cat); remove(path); return EXIT_FAILURE; }
    }
    cat_libera(&cat);
    remove(path);
    return EXIT_SUCCESS;
}
